// App.cpp -- demonstrating that vector stores COPIES
#include <cstdio>
#include <vector>
using namespace std;

class Integer {
    int Value;
public:
    Integer() : Value(0) {}
    Integer(int v) : Value(v) {}
    Integer(const Integer& v) : Value(v.Value) {}   // copy ctor used by vector
    void Set(int v) { Value = v; }
    int  Get()      { return Value; }
};

void main(void) {
    // 1. Build a stand-alone object
    vector<Integer> v;
    Integer i(5);

    // 2. push_back invokes Integer's copy constructor -- v[0] is now an INDEPENDENT object
    v.push_back(i);

    // 3. Mutate the original -- v[0] is unaffected
    i.Set(6);

    printf("i=%d, v[0]=%d\n", i.Get(), v[0].Get());
    // Output: i=6, v[0]=5
}

// Vector info & access methods
#include <vector>
using namespace std;

void main(void) {
    vector<int> v;
    v.reserve(1000);          // pre-allocate -- no reallocations for first 1000 push_backs
    for (int i = 0; i < 1000; ++i) v.push_back(i);

    // size() = elements currently stored
    // capacity() = slots allocated (>= size())
    // empty() = size() == 0
    // data() = T* pointer to the underlying contiguous storage (C++11)
    int  fast = v[10];       // operator[] -- NO bounds check in Release
    int  safe = v.at(10);    // at()       -- throws std::out_of_range
    int* raw  = v.data();    // direct pointer (interop with C APIs)

    (void)fast; (void)safe; (void)raw;
}

// deque -- O(1) at both ends, NO data()/reserve()/capacity()
#include <deque>
#include <array>
using namespace std;

void main(void) {
    // 1. deque: cheap insertion at front AND back
    deque<int> d;
    d.push_back(2);
    d.push_back(3);
    d.push_front(1);   // unique to deque/list -- vector lacks this
    // Layout (logically): 1, 2, 3
    // d.data()      -- COMPILE ERROR: not contiguous
    // d.reserve(10) -- COMPILE ERROR: no capacity to pre-pay

    // 2. std::array -- size in the type, full iterator support
    array<int, 5> a = { 10, 20, 30, 40, 50 };
    // a.push_back(60) -- COMPILE ERROR: array is fixed-size
    int sum = 0;
    for (int x : a) sum += x;
    (void)sum;
}

// list & forward_list -- iterator capability gap
#include <list>
#include <forward_list>
using namespace std;

void main(void) {
    // 1. list: bidirectional iterators -- ++ and -- work; + - < do NOT
    list<int> L = { 1, 2, 3, 4, 5 };
    auto it = L.begin();
    ++it;                   // OK
    --it;                   // OK
    // it + 2;             // COMPILE ERROR: not random-access
    // it < L.end();       // COMPILE ERROR: no relational operators

    // Special methods: merge two sorted lists, splice nodes between lists
    list<int> M = { 10, 20 };
    L.merge(M);             // M is consumed; L is sorted merge of both

    // 2. forward_list: insert AFTER the named iterator (no prev pointer)
    forward_list<int> F = { 1, 2, 3 };
    auto fit = F.begin();   // points at 1
    F.insert_after(fit, 99); // F = { 1, 99, 2, 3 }
    // F.push_back(4);      // COMPILE ERROR: no tail pointer
    // F.size();            // COMPILE ERROR: not stored
}

// stack / queue / priority_queue -- adaptors wrap a sequence container
#include <stack>
#include <queue>
#include <vector>
#include <list>
#include <functional>   // std::greater
using namespace std;

void main(void) {
    // 1. stack -- LIFO; default container is deque<T>
    stack<int> s;
    s.push(1); s.push(2); s.push(3);
    // s = [bottom 1, 2, 3 top]
    int t = s.top();    // 3
    s.pop();            // removes 3
    (void)t;

    // 2. queue -- FIFO; default container is deque<T>
    queue<int> q;
    q.push(10); q.push(20); q.push(30);
    int f = q.front();  // 10 (oldest)
    q.pop();            // removes 10
    (void)f;
    // queue<int, vector<int>> wrong;  // COMPILE ERROR: vector has no pop_front

    // 3. priority_queue -- max-heap by default; default container is vector<T>
    priority_queue<int> pq;
    pq.push(3); pq.push(7); pq.push(1);
    int hi = pq.top();  // 7 (largest, NOT smallest)
    pq.pop();           // removes 7
    (void)hi;

    // min-heap variant: pass std::greater
    priority_queue<int, vector<int>, greater<int>> pq_min;
    pq_min.push(3); pq_min.push(7); pq_min.push(1);
    int lo = pq_min.top(); // 1
    (void)lo;
}

// Manipulators -- change the formatting state of the stream
#include <iostream>
#include <iomanip>
#include <fstream>
using namespace std;

void main(void) {
    // 1. Base + boolean + precision manipulators
    cout << hex << 255 << "\n";          // ff
    cout << dec << 255 << "\n";          // 255
    cout << boolalpha << (1 < 2) << "\n"; // true (not 1)
    cout << setprecision(4) << 3.14159 << "\n"; // 3.142

    // 2. endl flushes; "\n" does not -- prefer "\n" in hot loops
    for (int i = 0; i < 1000; ++i) cout << i << "\n";   // fast
    for (int i = 0; i < 1000; ++i) cout << i << endl;   // slow: 1000 flushes

    // 3. File I/O -- same operator<<, just bound to an ofstream
    ofstream f("out.txt");
    if (f) f << "hello " << 42 << "\n";

    // 4. Binary mode -- raw bytes, no \r\n translation, use read/write
    ofstream bf("out.bin", ios::binary);
    int payload = 0x4142;
    bf.write(reinterpret_cast<const char*>(&payload), sizeof(payload));
}

// Strings -- construction, substring, view
#include <string>
#include <string_view>
#include <iostream>
using namespace std;

void main(void) {
    // 1. Owning string -- copies its buffer; cheap to manipulate
    string s1("Tomorrow");
    string s2(s1 + " I'll go ");         // s2 = "Tomorrow I'll go "
    string s3(s1, 3, 3);                  // substring: offset 3, length 3 -> "orr"
    string s6(10, '1');                   // 10 copies of '1' -> "1111111111"

    // 2. Non-owning view -- copy is JUST a pointer + length
    string_view sv = s1;                  // OK: s1 owns the buffer; sv points at it
    cout << sv.substr(0, 4) << "\n";      // "Tomo" -- substring without allocation

    // 3. TRAP: string_view::data() is NOT null-terminated
    string_view part = sv.substr(2, 3);   // points inside s1 -- no terminator at the end of the view
    // printf("%s", part.data());          // UB: reads past the view boundary
    cout << part << "\n";                 // OK: ostream uses (data, length) properly
}

// Brace-init with STL containers + the macro trap
#include <vector>
#include <map>
using namespace std;

// 1. Naive non-variadic macro -- BROKEN with brace-init
// #define DO_SOMETHING(x) x
// DO_SOMETHING( vector<int> x{1, 2, 3}; );
// Preprocessor sees 3 args: 'vector<int> x{1', ' 2', ' 3}; '
// Error: 'macro DO_SOMETHING passed 3 arguments, but takes just 1'

// 2. Variadic macro -- captures the whole expression including commas
#define DO_SOMETHING(...) __VA_ARGS__

void main(void) {
    DO_SOMETHING( vector<int> v{1, 2, 3}; );  // expands to: vector<int> v{1, 2, 3};

    // 3. Brace-init for map -- pair construction via inner braces
    map<const char*, int> grades = {
        { "Popescu", 10 },
        { "Ionescu", 9  },
        { "Popescu", 11 }   // DUP: silently ignored; map keeps the FIRST entry
    };
    // grades["Popescu"] == 10, NOT 11
    (void)v; (void)grades;
}

// Iterator usage patterns -- including the erase trap
#include <vector>
#include <list>
using namespace std;

void main(void) {
    // 1. Forward iteration -- works on any container that exposes begin()/end()
    vector<int> v = { 10, 20, 30, 40 };
    for (auto it = v.begin(); it != v.end(); ++it) {
        (void)*it;  // dereference
    }

    // 2. Range-for syntactic sugar -- generates the same iterator loop
    int sum = 0;
    for (int x : v) sum += x;

    // 3. Reverse iteration
    for (auto rit = v.rbegin(); rit != v.rend(); ++rit) {
        (void)*rit;  // walks 40, 30, 20, 10
    }

    // 4. The erase trap: don't reuse it after erase; capture the returned iterator
    for (auto it = v.begin(); it != v.end(); /* manual advance */) {
        if (*it % 2 == 0) {
            it = v.erase(it);   // erase returns the iterator AFTER the removed element
        } else {
            ++it;
        }
    }

    // 5. list iterator stability is stronger -- erase(it) leaves OTHER iterators valid
    list<int> L = { 1, 2, 3, 4 };
    auto a = L.begin();
    auto b = ++L.begin();          // points at 2
    L.erase(a);                    // a is now invalid, b is STILL VALID
    (void)*b;                      // OK: 2
    (void)sum;
}
